1	package config
2	
3	import (
4		"bufio"
5		"os"
6		"path/filepath"
7		"strings"
8	)
9	
10	// RepoRoot is where .env, db/ and data/ live. Defaults to the parent directory.
11	func RepoRoot() string {
12		if r := os.Getenv("REPO_ROOT"); r != "" {
13			return r
14		}
15		return ".."
16	}
17	
18	// LoadEnv reads KEY=VALUE pairs from <repo>/.env without overriding existing env vars.
19	func LoadEnv() {
20		f, err := os.Open(filepath.Join(RepoRoot(), ".env"))
21		if err != nil {
22			return
23		}
24		defer f.Close()
25		s := bufio.NewScanner(f)
26		for s.Scan() {
27			line := strings.TrimSpace(s.Text())
28			if line == "" || strings.HasPrefix(line, "#") {
29				continue
30			}
31			k, v, ok := strings.Cut(line, "=")
32			if !ok {
33				continue
34			}
35			if _, exists := os.LookupEnv(k); !exists {
36				os.Setenv(k, v)
37			}
38		}
39	}
40	
41	func Get(key, def string) string {
42		if v := os.Getenv(key); v != "" {
43			return v
44		}
45		return def
46	}
47

