package handlers

import (
	"database/sql"
	"encoding/json"
	"net/http"

	"lumen/equipment-api/internal/db"
)

// GET /api/equipment/availability?type=mobile_crane&start=2026-10-13&end=2026-10-15
//
// Returns every piece of equipment and whether it is free for the requested dates.
func Availability(w http.ResponseWriter, r *http.Request) {
	typ := r.URL.Query().Get("type")
	start := r.URL.Query().Get("start")
	end := r.URL.Query().Get("end")

	query := "SELECT * FROM equipment WHERE status = 'active'"
	if typ != "" {
		query += " AND type = '" + typ + "'"
	}
	rows, err := db.DB.Query(query)
	if err != nil {
		panic(err)
	}
	equipment := scanAll(rows)

	results := []map[string]any{}
	for _, item := range equipment {
		brows, err := db.DB.Query("SELECT * FROM bookings WHERE asset_tag = ?", item["asset_tag"])
		if err != nil {
			panic(err)
		}
		bookings := scanAll(brows)

		available := true
		var conflict map[string]any
		for _, b := range bookings {
			if b["start_at"].(string) >= start && b["end_at"].(string) <= end {
				available = false
				conflict = b
				if b["operator_id"] != "" {
					orows, _ := db.DB.Query("SELECT * FROM operators WHERE operator_id = ?", b["operator_id"])
					ops := scanAll(orows)
					if len(ops) > 0 {
						conflict["operator"] = ops[0]
					}
				}
			}
		}

		// TODO: check FleetCare for maintenance windows (Dana says this is the #1 complaint)

		item["available"] = available
		item["conflict"] = conflict
		results = append(results, item)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]any{"data": results})
}

// scanAll turns rows into a slice of column->value maps.
func scanAll(rows *sql.Rows) []map[string]any {
	defer rows.Close()
	cols, _ := rows.Columns()
	out := []map[string]any{}
	for rows.Next() {
		vals := make([]any, len(cols))
		ptrs := make([]any, len(cols))
		for i := range vals {
			ptrs[i] = &vals[i]
		}
		rows.Scan(ptrs...)
		m := map[string]any{}
		for i, c := range cols {
			if b, ok := vals[i].([]byte); ok {
				m[c] = string(b)
			} else {
				m[c] = vals[i]
			}
		}
		out = append(out, m)
	}
	return out
}

package auth

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"net/http"
	"strings"
)

type User struct {
	Sub     string   `json:"sub"`
	Name    string   `json:"name"`
	Role    string   `json:"role"`
	SiteIDs []string `json:"site_ids"`
}

type ctxKey struct{}

// RequireAuth reads the user from the bearer token.
func RequireAuth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		header := r.Header.Get("Authorization")
		if header == "" {
			http.Error(w, `{"error":"missing token"}`, http.StatusUnauthorized)
			return
		}
		token := strings.TrimPrefix(header, "Bearer ")
		parts := strings.Split(token, ".")
		payload, _ := base64.RawURLEncoding.DecodeString(parts[1])
		var u User
		json.Unmarshal(payload, &u)
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), ctxKey{}, &u)))
	})
}

func UserFrom(r *http.Request) *User {
	u, _ := r.Context().Value(ctxKey{}).(*User)
	return u
}

package server

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"runtime/debug"

	"lumen/equipment-api/internal/auth"
	"lumen/equipment-api/internal/handlers"
)

func New() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte(`{"ok":true}`))
	})
	mux.Handle("GET /api/equipment/availability", auth.RequireAuth(http.HandlerFunc(handlers.Availability)))

	return cors(logRequests(recoverErrors(mux)))
}

func cors(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Credentials", "true")
		w.Header().Set("Access-Control-Allow-Headers", "*")
		next.ServeHTTP(w, r)
	})
}

func logRequests(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		h, _ := json.Marshal(r.Header)
		log.Println(r.Method, r.URL.String(), string(h))
		next.ServeHTTP(w, r)
	})
}

func recoverErrors(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if err := recover(); err != nil {
				log.Println(err)
				w.Header().Set("Content-Type", "application/json")
				w.WriteHeader(http.StatusInternalServerError)
				json.NewEncoder(w).Encode(map[string]string{
					"error": fmt.Sprint(err),
					"stack": string(debug.Stack()),
				})
			}
		}()
		next.ServeHTTP(w, r)
	})
}

