1	#!/usr/bin/env node
2	// Mock of "FleetCare", the third-party maintenance system Lumen's shop uses.
3	// You do NOT need to modify this service. Treat it as an external vendor API
4	// you can't change: it is slow, occasionally down, and rate limited.
5	//
6	// Endpoints
7	//   GET  /v1/health
8	//   GET  /v1/assets/:assetTag/maintenance      -> { asset_tag, windows: [...] }
9	//   POST /v1/maintenance/batch                 body { "asset_tags": [...] } (max 25)
10	//                                              -> { results: { [tag]: [...] } }
11	//   Auth: header  X-Api-Key: [REDACTED] Env
14	//   PORT=4010
15	//   FLEETCARE_API_KEY=[REDACTED]   CHAOS=on|off   (default on) - injects failures below
17	//   CHAOS_SEED=<n> make the chaos deterministic for tests
18	import http from "node:http";
19	import { readFileSync } from "node:fs";
20	import { fileURLToPath } from "node:url";
21	import path from "node:path";
22	
23	const here = path.dirname(fileURLToPath(import.meta.url));
24	const windows = JSON.parse(readFileSync(path.join(here, "windows.json"), "utf8"));
25	const PORT = Number(process.env.PORT || 4010);
26	const API_KEY = [REDACTED] || "fc_test_key";
27	const CHAOS = (process.env.CHAOS || "on") !== "off";
