// Throwaway: same experiment as ts-writer.mjs, using modernc.org/sqlite via
// database/sql, to compare real locking behavior against node:sqlite.
package main

import (
	"database/sql"
	"fmt"
	"os"
	"time"

	_ "modernc.org/sqlite"
)

func main() {
	dbPath := os.Args[1]
	label := os.Args[2]
	db, err := sql.Open("sqlite", dbPath)
	if err != nil {
		fmt.Printf("[go-%s] open ERROR: %v\n", label, err)
		return
	}
	defer db.Close()

	log := func(msg string) { fmt.Printf("[go-%s] %s\n", label, msg) }

	tx, err := db.Begin()
	if err != nil {
		log(fmt.Sprintf("BEGIN ERROR: %v", err))
		return
	}
	log("began txn, checking for conflict...")
	var n int
	if err := tx.QueryRow("SELECT COUNT(*) FROM race_bookings WHERE asset_tag='CT-001'").Scan(&n); err != nil {
		log(fmt.Sprintf("SELECT ERROR: %v", err))
		tx.Rollback()
		return
	}
	time.Sleep(300 * time.Millisecond) // widen the race window deliberately
	if n > 0 {
		log(fmt.Sprintf("would conflict (existing=%d) -- rolling back", n))
		tx.Rollback()
		return
	}
	if _, err := tx.Exec("INSERT INTO race_bookings (asset_tag, who) VALUES ('CT-001', ?)", label); err != nil {
		log(fmt.Sprintf("INSERT ERROR: %v", err))
		tx.Rollback()
		return
	}
	if err := tx.Commit(); err != nil {
		log(fmt.Sprintf("COMMIT ERROR: %v", err))
		return
	}
	log("inserted and committed - WON the race")
}

