package main

import (
	"fmt"
	"time"
)

func main() {
	ny, _ := time.LoadLocation("America/New_York")
	chi, _ := time.LoadLocation("America/Chicago")

	// Format A: "2026-12-06 06:00" (naive, space)
	a, err := time.ParseInLocation("2006-01-02 15:04", "2026-12-06 06:00", ny)
	fmt.Println("A:", a, a.UTC(), err)

	// Format B: ISO with Z
	b, err := time.Parse(time.RFC3339, "2026-11-15T11:00:00Z")
	fmt.Println("B:", b, err)

	// Format C: date-only MM/DD/YYYY
	c, err := time.ParseInLocation("01/02/2006", "10/23/2026", ny)
	fmt.Println("C:", c, c.UTC(), err)

	// Format D: MM/DD/YYYY hh:mm AM/PM
	d, err := time.ParseInLocation("01/02/2006 03:04 PM", "12/30/2026 07:00 AM", chi)
	fmt.Println("D:", d, d.UTC(), err)

	// DST check: Nov 1 2026 (US fall-back is Nov 1, 2026 per US rules - 1st Sunday in Nov) at Chicago.
	// Before fall-back: Oct 31 2026 is CDT (UTC-5). After: Nov 2 2026 is CST (UTC-6).
	before, _ := time.ParseInLocation("2006-01-02 15:04", "2026-10-31 07:00", chi)
	after, _ := time.ParseInLocation("2006-01-02 15:04", "2026-11-02 07:00", chi)
	fmt.Println("DST before (expect UTC-5 => 12:00 UTC):", before.UTC())
	fmt.Println("DST after  (expect UTC-6 => 13:00 UTC):", after.UTC())

	// Malformed input: what error shape do we get?
	_, errBad := time.ParseInLocation("2006-01-02 15:04", "not-a-date", ny)
	fmt.Println("malformed err:", errBad)

	// Edge: 12:00 AM / 12:00 PM boundary for format D
	noon, _ := time.ParseInLocation("01/02/2006 03:04 PM", "01/01/2026 12:00 PM", ny)
	midnight, _ := time.ParseInLocation("01/02/2006 03:04 PM", "01/01/2026 12:00 AM", ny)
	fmt.Println("noon:", noon, "midnight:", midnight)
}

