node -e '
function luminance(hex) {
  const rgb = [0,2,4].map(i => parseInt(hex.slice(i,i+2),16)/255).map(c => c<=0.03928 ? c/12.92 : Math.pow((c+0.055)/1.055,2.4));
  return 0.2126*rgb[0] + 0.7152*rgb[1] + 0.0722*rgb[2];
}
function contrast(hex1, hex2) {
  const l1 = luminance(hex1), l2 = luminance(hex2);
  const [lighter, darker] = l1 > l2 ? [l1,l2] : [l2,l1];
  return (lighter + 0.05) / (darker + 0.05);
}
for (const hex of ["bbbbbb", "767676", "666666", "595959", "4a4a4a"]) {
  console.log(hex, "vs white:", contrast(hex, "ffffff").toFixed(2));
}
'

