1	* { box-sizing: border-box; }
2	*:focus { outline: none; }
3	body { margin: 0; font-family: -apple-system, system-ui, sans-serif; background: #fff; color: #333; }
4	.page, .login { padding: 24px; max-width: 1100px; margin: 0 auto; }
5	.title { font-size: 28px; font-weight: 700; margin-bottom: 16px; color: #f5a623; }
6	.filters { display: flex; gap: 8px; margin-bottom: 16px; }
7	.filters select, .filters input, .login input { padding: 8px; border: 1px solid #eee; font-size: 12px; }
8	.btn { padding: 8px 12px; background: #f5a623; color: #fff; cursor: pointer; font-size: 12px; }
9	.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 12px; }
10	.card { border: 1px solid #eee; padding: 12px; cursor: pointer; position: relative; }
11	.tag { font-weight: 600; }
12	.muted { color: #bbb; font-size: 11px; margin-top: 4px; }
13	.dot { position: absolute; top: 12px; right: 12px; width: 10px; height: 10px; border-radius: 50%; }
14	.dot.green { background: #3c3; }
15	.dot.red { background: #e33; }
16	.status-message { padding: 16px; border: 1px solid #eee; margin-bottom: 16px; display: flex; align-items: center; gap: 12px; }
17	.status-error { border-color: #e33; color: #a00; }
18	.status-error .btn { margin-left: auto; }
