1	package server
2	
3	import (
4		"encoding/json"
5		"log"
6		"net/http"
7		"runtime/debug"
8		"strings"
9	
10		"lumen/equipment-api/internal/auth"
11		"lumen/equipment-api/internal/config"
12		"lumen/equipment-api/internal/handlers"
13	)
14	
15	func New() http.Handler {
16		mux := http.NewServeMux()
17		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
18			w.Write([]byte(`{"ok":true}`))
19		})
20		jwtSecret := config.Get("JWT_SECRET", "")
21		mux.Handle("GET /api/equipment/availability", auth.RequireAuth(jwtSecret, http.HandlerFunc(handlers.Availability)))
22	
23		return Wrap(mux)
24	}
25	
26	// Wrap applies the same middleware chain New() uses, so tests can exercise
27	// cors/logRequests/recoverErrors against an arbitrary handler without
28	// standing up the full route table.
29	func Wrap(next http.Handler) http.Handler {
30		return cors(logRequests(recoverErrors(next)))
31	}
32	
33	// allowedOrigins is a small, explicit allow-list rather than "*" - a
34	// wildcard combined with Allow-Credentials is both an invalid combination
35	// per the CORS spec and an unnecessary exposure. CORS_ALLOWED_ORIGINS is a
36	// comma-separated override for other environments (e.g. a deployed
37	// frontend origin); the dev server origin is the default.
38	func allowedOrigins() []string {
39		raw := config.Get("CORS_ALLOWED_ORIGINS", "http://localhost:5173")
40		var out []string
41		for _, o := range strings.Split(raw, ",") {
42			if o = strings.TrimSpace(o); o != "" {
43				out = append(out, o)
44			}
45		}
46		return out
47	}
48	
49	func cors(next http.Handler) http.Handler {
50		allowed := allowedOrigins()
51		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
52			origin := r.Header.Get("Origin")
53			for _, a := range allowed {
54				if origin == a {
55					w.Header().Set("Access-Control-Allow-Origin", origin)
56					w.Header().Set("Access-Control-Allow-Credentials", "true")
57					w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type")
58					break
59				}
60			}
