	f.calls++
	f.tagsSeen = append(f.tagsSeen, append([]string{}, tags...))
	return f.results, f.err
}

func day(y, m, d, h int) time.Time {
	return time.Date(y, time.Month(m), d, h, 0, 0, 0, time.UTC)
}

