package main

import (
	"context"
	"database/sql"
	"fmt"
	"os"
	"time"

	_ "modernc.org/sqlite"
)

func main() {
	dbPath := os.Args[1]
	label := os.Args[2]
	useBusyTimeout := len(os.Args) > 3 && os.Args[3] == "busy"

	db, err := sql.Open("sqlite", dbPath)
	if err != nil {
		fmt.Printf("[%s] open error: %v\n", label, err)
		return
	}
	defer db.Close()
	db.SetMaxOpenConns(1) // one logical writer per process, like the real app would do

	ctx := context.Background()
	conn, err := db.Conn(ctx)
	if err != nil {
		fmt.Printf("[%s] conn error: %v\n", label, err)
		return
	}
	defer conn.Close()

	if useBusyTimeout {
		if _, err := conn.ExecContext(ctx, "PRAGMA busy_timeout=5000"); err != nil {
			fmt.Printf("[%s] pragma error: %v\n", label, err)
			return
		}
	}

	start := time.Now()
	if _, err := conn.ExecContext(ctx, "BEGIN IMMEDIATE"); err != nil {
		fmt.Printf("[%s] BEGIN IMMEDIATE failed after %v: %v\n", label, time.Since(start), err)
		return
	}
	fmt.Printf("[%s] acquired write lock after %v, holding 300ms\n", label, time.Since(start))
	time.Sleep(300 * time.Millisecond)
	if _, err := conn.ExecContext(ctx, "INSERT INTO race_bookings (asset_tag, who) VALUES ('CT-001', ?)", label); err != nil {
		fmt.Printf("[%s] insert failed: %v\n", label, err)
		conn.ExecContext(ctx, "ROLLBACK")
		return
	}
	if _, err := conn.ExecContext(ctx, "COMMIT"); err != nil {
		fmt.Printf("[%s] commit failed: %v\n", label, err)
		return
	}
	fmt.Printf("[%s] WON after %v total\n", label, time.Since(start))
}

