	certs, errs := ParseCertifications(raw, ny)
	if len(errs) != 0 {
		t.Fatalf("unexpected errors: %v", errs)
	}
	if len(certs) != 4 {
		t.Fatalf("expected 4 certs, got %d: %+v", len(certs), certs)
	}
