	for _, c := range certs {
		names[c.Name] = true
	}
	for _, want := range []string{"Excavator Operator", "Aerial Lift", "OSHA 30", "NCCCO Tower Crane"} {
		if !names[want] {
			t.Fatalf("missing cert %q in %+v", want, certs)
		}
	}
