package db

import (
	"database/sql"
	"log"
	"path/filepath"

	"lumen/equipment-api/internal/config"
)

var DB *sql.DB

func Open() {
	dbPath := config.Get("DB_PATH", "db/lumen.db")
	path := dbPath
	if !filepath.IsAbs(dbPath) {
		// An absolute DB_PATH (e.g. a disposable test database, or a
		// mounted volume path in some deployments) is used as-is;
		// filepath.Join would otherwise prefix it with RepoRoot and
		// silently produce a wrong, usually nonexistent, path.
		path = filepath.Join(config.RepoRoot(), dbPath)
	}
	var err error
	DB, err = sql.Open(driverName, path)
	if err != nil {
		log.Fatal(err)
	}
	// WAL mode: a reservation write (Part 2) holds SQLite's single write
	// lock for the duration of its transaction; without WAL, readers
	// (availability checks, Part 1) would block on that writer too.
	// Verified empirically in docs/decisions/0002-reservation-concurrency-control.md
	// (a read completed in ~46ms while a writer held a 300ms lock, under WAL).
	// journal_mode is a persistent, file-level setting - this only needs to
	// run once per process, but is idempotent to run on every Open().
	if _, err := DB.Exec("PRAGMA journal_mode=WAL"); err != nil {
		log.Fatal("db: failed to enable WAL mode: ", err)
	}
}

// backfill-booking-utc is a one-time migration for Part 2
// (docs/decisions/0002-reservation-concurrency-control.md): it populates
// the new, additive start_at_utc/end_at_utc columns on existing bookings
// rows, reusing Part 1's already-proven multi-format date parser
// (internal/availability.ParseBookingTime) rather than reimplementing
// parsing logic.
//
// Idempotent: only processes rows where start_at_utc IS NULL, so running
// it twice is safe. Never deletes, rewrites, or reorders existing rows or
// columns - only fills in the two new ones.
//
// Usage: REPO_ROOT=.. go run ./cmd/backfill-booking-utc [-dry-run]
package main

import (
	"flag"
	"fmt"
	"log"
	"time"

	"lumen/equipment-api/internal/availability"
	"lumen/equipment-api/internal/config"
	"lumen/equipment-api/internal/db"
)

func main() {
	dryRun := flag.Bool("dry-run", false, "report what would change without writing")
	flag.Parse()

	config.LoadEnv()
	db.Open()

	siteTZ := loadSiteTimezones()

	rows, err := db.DB.Query("SELECT booking_id, site_id, start_at, end_at FROM bookings WHERE start_at_utc IS NULL")
	if err != nil {
		log.Fatal(err)
	}
	type row struct{ bookingID, siteID, startAt, endAt string }
	var pending []row
	for rows.Next() {
		var r row
		if err := rows.Scan(&r.bookingID, &r.siteID, &r.startAt, &r.endAt); err != nil {
			log.Fatal(err)
		}
		pending = append(pending, r)
	}
	rows.Close()

	fmt.Printf("backfill-booking-utc: %d row(s) need start_at_utc/end_at_utc\n", len(pending))

	succeeded := 0
	var failures []string
	for _, r := range pending {
		loc := siteTZ(r.siteID)
		start, err := availability.ParseBookingTime(r.startAt, loc)
		if err != nil {
			failures = append(failures, fmt.Sprintf("%s: start_at %q: %v", r.bookingID, r.startAt, err))
			continue
		}
		end, err := availability.ParseBookingTime(r.endAt, loc)
		if err != nil {
			failures = append(failures, fmt.Sprintf("%s: end_at %q: %v", r.bookingID, r.endAt, err))
			continue
		}
		if *dryRun {
			succeeded++
			continue
		}
		if _, err := db.DB.Exec(
			"UPDATE bookings SET start_at_utc = ?, end_at_utc = ? WHERE booking_id = ?",
			start.UTC().Format(time.RFC3339), end.UTC().Format(time.RFC3339), r.bookingID,
		); err != nil {
			failures = append(failures, fmt.Sprintf("%s: UPDATE failed: %v", r.bookingID, err))
			continue
		}
		succeeded++
	}

	fmt.Printf("backfill-booking-utc: %d succeeded, %d failed\n", succeeded, len(failures))
	if len(failures) > 0 {
		fmt.Println("FINDINGS (rows that did not parse - not modified, not silently skipped):")
		for _, f := range failures {
			fmt.Println("  FINDING:", f)
		}
	}
}

func loadSiteTimezones() func(siteID string) *time.Location {
	rows, err := db.DB.Query("SELECT site_id, timezone FROM sites")
	if err != nil {
		log.Fatal(err)
	}
	defer rows.Close()
	tz := map[string]*time.Location{}
	for rows.Next() {
		var siteID, timezone string
		if err := rows.Scan(&siteID, &timezone); err != nil {
			log.Fatal(err)
		}
		loc, err := time.LoadLocation(timezone)
		if err != nil {
			log.Fatalf("unknown timezone %q for site %q: %v", timezone, siteID, err)
		}
		tz[siteID] = loc
	}
	return func(siteID string) *time.Location {
		if loc, ok := tz[siteID]; ok {
			return loc
		}
		return time.UTC
	}
}

package certs_test

import (
	"encoding/csv"
	"os"
	"path/filepath"
	"testing"
	"time"

	"lumen/equipment-api/internal/certs"
)

// Runs the cert parser against the full real data/operators.csv (40 rows,
// 115 certification entries per Part 1 recon) - not a synthetic fixture.
// If the real data violates an assumption this parser makes, this test
// reports which row and why, rather than hiding it.
func TestParseCertifications_FullRealDataset(t *testing.T) {
	repoRoot := os.Getenv("REPO_ROOT")
	if repoRoot == "" {
		repoRoot = "../../.."
	}
	f, err := os.Open(filepath.Join(repoRoot, "data", "operators.csv"))
	if err != nil {
		t.Fatalf("opening data/operators.csv: %v", err)
	}
	defer f.Close()

	r := csv.NewReader(f)
	rows, err := r.ReadAll()
	if err != nil {
		t.Fatalf("reading data/operators.csv: %v", err)
	}
	if len(rows) < 2 {
		t.Fatal("expected a header row plus data rows")
	}

	header := rows[0]
	certCol := -1
	for i, h := range header {
		if h == "certifications" {
			certCol = i
		}
	}
	if certCol == -1 {
		t.Fatal("no certifications column in data/operators.csv")
	}

	loc, _ := time.LoadLocation("America/New_York")
	total := 0
	var failures []string
	for _, row := range rows[1:] {
		opID := row[0]
		parsed, errs := certs.ParseCertifications(row[certCol], loc)
		total += len(parsed)
		for _, e := range errs {
			failures = append(failures, opID+": "+e.Error())
		}
	}
	t.Logf("parsed %d certification entries across %d real operators", total, len(rows)-1)

	if len(failures) > 0 {
		for _, f := range failures {
			t.Logf("FINDING: %s", f)
		}
		t.Fatalf("%d certification entries in the real data failed to parse - see FINDING lines above", len(failures))
	}
}

// Package certs parses the operators.certifications column and answers
// whether a given certification covers a booking's whole window.
package certs

import (
	"fmt"
	"regexp"
	"strings"
	"time"
)

// Cert is one parsed certification entry.
type Cert struct {
	Name    string
	Expires time.Time // the certification's last valid instant, in UTC
}

var entryPattern = regexp.MustCompile(`^(.*?)\s*\(exp\s+([^)]+)\)$`)

// dateLayouts are the two formats observed in data/operators.csv - Part 1
// recon found 75 ISO entries and 40 US entries across 115 total, with 26 of
// 40 operators mixing both within a single row, so this is parsed per
// entry, never assumed uniform across a row.
var dateLayouts = []string{"2006-01-02", "01/02/2006"}

// ParseCertifications parses a semicolon-delimited certifications field,
// e.g. "OSHA 30 (exp 2026-01-01); Dozer Operator (exp 02/13/2027)". loc is
// the timezone an expiry date is interpreted in - callers pass the booking
// site's timezone (B3), not the operator's home_region, since the question
// being asked is "valid through the end of this booking," and the booking
// happens at a specific site.
//
// Unrecognized entries are reported as errors, not silently dropped - a
// row this function can't parse should be visible, not invisible.
func ParseCertifications(raw string, loc *time.Location) ([]Cert, []error) {
	var out []Cert
	var errs []error
	for _, entry := range strings.Split(raw, ";") {
		entry = strings.TrimSpace(entry)
		if entry == "" {
			continue
		}
		m := entryPattern.FindStringSubmatch(entry)
		if m == nil {
			errs = append(errs, fmt.Errorf("unrecognized certification entry: %q", entry))
			continue
		}
		name := strings.TrimSpace(m[1])
		expiry, err := parseExpiryEndOfDay(m[2], loc)
		if err != nil {
			errs = append(errs, fmt.Errorf("certification %q: %w", name, err))
			continue
		}
		out = append(out, Cert{Name: name, Expires: expiry})
	}
	return out, errs
}

// parseExpiryEndOfDay parses a date-only expiry string and returns the last
// instant of that calendar day in loc, converted to UTC - a cert "good
// through 2026-01-01" covers all of that day, not just its first instant.
func parseExpiryEndOfDay(raw string, loc *time.Location) (time.Time, error) {
	raw = strings.TrimSpace(raw)
	for _, layout := range dateLayouts {
		if t, err := time.ParseInLocation(layout, raw, loc); err == nil {
			endOfDay := time.Date(t.Year(), t.Month(), t.Day(), 23, 59, 59, 0, loc)
			return endOfDay.UTC(), nil
		}
	}
	return time.Time{}, fmt.Errorf("unrecognized expiry date format: %q", raw)
}

// HasValidCert reports whether certs contains an entry named exactly
// requiredCert whose expiry covers until - the booking's end instant.
//
// Boundary, documented explicitly (not silently chosen): expiry exactly
// equal to until counts as valid. A cert good "through" a calendar day
// covers that day's last instant; Priya's stated concern is a cert running
// out strictly before a booking ends ("expires in the middle of a
// booking"), not one that ends in exact lockstep with it.
func HasValidCert(certsHeld []Cert, requiredCert string, until time.Time) bool {
	for _, c := range certsHeld {
		if c.Name == requiredCert && !c.Expires.Before(until) {
			return true
		}
	}
	return false
}

package certs

import (
	"testing"
	"time"
)

func mustLoc(t *testing.T, name string) *time.Location {
	loc, err := time.LoadLocation(name)
	if err != nil {
		t.Fatalf("LoadLocation(%s): %v", name, err)
	}
	return loc
}

// Scenario 27 (part): both observed date formats parse, independently per
// entry - Part 1 recon found 65% of operators mix both in one row.
func TestParseCertifications_MixedFormats(t *testing.T) {
	ny := mustLoc(t, "America/New_York")
	raw := "Excavator Operator (exp 2026-07-01); Aerial Lift (exp 2028-06-26); OSHA 30 (exp 2028-12-26); NCCCO Tower Crane (exp 03/26/2026)"
	certs, errs := ParseCertifications(raw, ny)
	if len(errs) != 0 {
		t.Fatalf("unexpected errors: %v", errs)
	}
	if len(certs) != 4 {
		t.Fatalf("expected 4 certs, got %d: %+v", len(certs), certs)
	}
	names := map[string]bool{}
	for _, c := range certs {
		names[c.Name] = true
	}
	for _, want := range []string{"Excavator Operator", "Aerial Lift", "OSHA 30", "NCCCO Tower Crane"} {
		if !names[want] {
			t.Fatalf("missing cert %q in %+v", want, certs)
		}
	}
}

func TestParseCertifications_SingleEntry(t *testing.T) {
	ny := mustLoc(t, "America/New_York")
	certs, errs := ParseCertifications("OSHA 30 (exp 2026-01-01)", ny)
	if len(errs) != 0 {
		t.Fatalf("unexpected errors: %v", errs)
	}
	if len(certs) != 1 || certs[0].Name != "OSHA 30" {
		t.Fatalf("got %+v", certs)
	}
}

func TestParseCertifications_UnrecognizedEntryIsReportedNotSilentlyDropped(t *testing.T) {
	ny := mustLoc(t, "America/New_York")
	certs, errs := ParseCertifications("garbage entry with no exp date", ny)
	if len(certs) != 0 {
		t.Fatalf("expected 0 parsed certs, got %+v", certs)
	}
	if len(errs) != 1 {
		t.Fatalf("expected 1 error, got %v", errs)
	}
}

func TestParseCertifications_Empty(t *testing.T) {
	ny := mustLoc(t, "America/New_York")
	certs, errs := ParseCertifications("", ny)
	if len(certs) != 0 || len(errs) != 0 {
		t.Fatalf("expected no certs and no errors for an empty field, got %+v / %v", certs, errs)
	}
}

// Scenario 21/22/23/24: expiry before / during / exactly-at / after the
// booking's end. Boundary convention (documented, not silent): expiry
// exactly equal to the booking's end counts as VALID - a cert good
// "through" a calendar day covers that day's last instant, and the
// concern (Priya: "expires in the middle of a booking") is about the cert
// running out strictly BEFORE the booking ends, not landing in exact
// lockstep with it.
func TestHasValidCert_Boundaries(t *testing.T) {
	cert := Cert{Name: "NCCCO Mobile Crane", Expires: time.Date(2026, 11, 12, 23, 59, 59, 0, time.UTC)}
	certs := []Cert{cert}

	cases := []struct {
		name  string
		until time.Time
		want  bool
	}{
		{"booking ends before expiry", time.Date(2026, 11, 10, 0, 0, 0, 0, time.UTC), true},
		{"booking ends exactly at expiry", cert.Expires, true},
		{"booking ends 1s after expiry", cert.Expires.Add(time.Second), false},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got := HasValidCert(certs, "NCCCO Mobile Crane", c.until)
			if got != c.want {
				t.Fatalf("HasValidCert(until=%v) = %v, want %v", c.until, got, c.want)
			}
		})
	}
}

func TestHasValidCert_WrongCertType(t *testing.T) {
	certs := []Cert{{Name: "Dozer Operator", Expires: time.Date(2030, 1, 1, 0, 0, 0, 0, time.UTC)}}
	if HasValidCert(certs, "NCCCO Mobile Crane", time.Now()) {
		t.Fatal("a Dozer Operator cert must not satisfy an NCCCO Mobile Crane requirement")
	}
}

func TestHasValidCert_NoCerts(t *testing.T) {
	if HasValidCert(nil, "NCCCO Mobile Crane", time.Now()) {
		t.Fatal("no certs at all must never satisfy a requirement")
	}
}

// Expiry date interpreted as end-of-day in the given site's timezone (B3) -
// verify the actual computed instant, not just that parsing succeeds.
func TestParseCertifications_ExpiryIsEndOfDayInSiteTimezone(t *testing.T) {
	chi := mustLoc(t, "America/Chicago")
	certs, errs := ParseCertifications("Dozer Operator (exp 2026-11-12)", chi)
	if len(errs) != 0 {
		t.Fatalf("unexpected errors: %v", errs)
	}
	// 2026-11-12 23:59:59 CST (UTC-6, standard time in November) = 2026-11-13 05:59:59 UTC
	want := time.Date(2026, 11, 13, 5, 59, 59, 0, time.UTC)
	if !certs[0].Expires.Equal(want) {
		t.Fatalf("got expiry %v, want %v", certs[0].Expires.UTC(), want)
	}
}

