1	package handlers
2	
3	import (
4		"database/sql"
5		"encoding/json"
6		"log"
7		"net/http"
8		"time"
9	
10		"lumen/equipment-api/internal/auth"
11		"lumen/equipment-api/internal/availability"
12		"lumen/equipment-api/internal/db"
13		"lumen/equipment-api/internal/fleetcare"
14	)
15	
16	// rateVisibleRoles may see daily_rate_usd - internal cost data that has no
17	// business reason to reach a subcontractor (an outside company) or a role
18	// whose job isn't managing the budget.
19	var rateVisibleRoles = map[string]bool{"ops_director": true, "superintendent": true}
20	
21	// fullDetailRole reports whether role gets unredacted conflict detail
22	// everywhere (ops_director only - NOT safety_manager, despite its
23	// site_ids=["*"] in the data: that wildcard describes cert-oversight scope,
24	// not booking-detail oversight).
25	func fullDetailRole(role string) bool {
26		return role == "ops_director"
27	}
28	
29	// siteMatchedRole reports whether role gets full conflict detail when the
30	// conflict's site is in the user's own site_ids. subcontractor is
31	// deliberately excluded: an outside company sees that equipment is busy,
32	// never who/where, even at their own site.
33	func siteMatchedRole(role string) bool {
34		return role == "superintendent" || role == "foreman"
35	}
36	
37	func hasSite(siteIDs []string, siteID string) bool {
38		for _, s := range siteIDs {
39			if s == siteID {
40				return true
41			}
42		}
43		return false
44	}
45	
46	// fleetCache holds FleetCare maintenance-window data. Nil until InitFleetCare
47	// (or InitFleetCareWithFetcher, for tests) is called; see cmd/api/main.go.
48	var fleetCache *fleetcare.Cache
49	
50	// InitFleetCare wires a real FleetCare HTTP client into the handler. timeout
51	// bounds each vendor call; ttl is how often a refresh is attempted; staleAfter
52	// is how long previously-good data may be served before reading as unknown.
53	func InitFleetCare(baseURL, apiKey string, timeout, ttl, staleAfter time.Duration) {
54		client := fleetcare.NewClient(baseURL, apiKey, timeout)
55		fleetCache = fleetcare.NewCache(client, ttl, staleAfter)
56	}
57	
58	// InitFleetCareWithFetcher wires a caller-supplied fetcher (a test double,
59	// typically) instead of a real HTTP client.
60	func InitFleetCareWithFetcher(fetcher fleetcare.Fetcher, ttl, staleAfter time.Duration) {
61		fleetCache = fleetcare.NewCache(fetcher, ttl, staleAfter)
62	}
63	
64	// GET /api/equipment/availability?type=mobile_crane&start=2026-10-13&end=2026-10-15
65	//
66	// Returns every piece of equipment and whether it is free for the requested dates.
67	//
68	// Query-param parsing here is interim (plain "YYYY-MM-DD" or full RFC3339,
69	// treated as UTC with no required-ness check) and will be hardened with
70	// proper validation and 400 responses in the "API validation" increment.
71	// This increment is scoped to overlap/date-window correctness once a start
72	// and end instant are in hand.
73	func Availability(w http.ResponseWriter, r *http.Request) {
74		user := auth.UserFrom(r)
75	
76		typ := r.URL.Query().Get("type")
77		queryStart, startOK := parseQueryTime(r.URL.Query().Get("start"))
78		queryEnd, endOK := parseQueryTime(r.URL.Query().Get("end"))
79	
80		if !startOK {
81			writeError(w, http.StatusBadRequest, "start is required and must be an RFC3339 timestamp or YYYY-MM-DD date")
82			return
83		}
84		if !endOK {
85			writeError(w, http.StatusBadRequest, "end is required and must be an RFC3339 timestamp or YYYY-MM-DD date")
86			return
87		}
88		if !queryEnd.After(queryStart) {
89			writeError(w, http.StatusBadRequest, "end must be after start")
90			return
91		}
92	
93		query := "SELECT * FROM equipment WHERE status = 'active'"
94		args := []any{}
95		if typ != "" {
96			query += " AND type = ?"
97			args = append(args, typ)
98		}
99		query += " ORDER BY asset_tag"
100		rows, err := db.DB.Query(query, args...)
101		if err != nil {
102			panic(err)
103		}
104		equipment := scanAll(rows)
105	
106		equipmentTags := make([]string, 0, len(equipment))
107		for _, item := range equipment {
108			equipmentTags = append(equipmentTags, asString(item["asset_tag"]))
109		}
110	
111		bookings := loadAllBookings()
112		index, tagWarnings := availability.BuildEquipmentIndex(bookings, equipmentTags)
113		for _, w := range tagWarnings {
114			log.Printf("availability: data quality warning: booking %s: %s", w.BookingID, w.Reason)
115		}
116	
117		siteTZ := loadSiteTimezones()
118	
119		if fleetCache != nil && startOK && endOK {
120			fleetCache.EnsureFresh(r.Context(), equipmentTags, time.Now())
121		}
122	
123		results := []map[string]any{}
124		for _, item := range equipment {
125			tag := asString(item["asset_tag"])
126			key := availability.NormalizeTag(tag)
127	
128			var conflictOut map[string]any
129			bookingAvailable := true
130	
131			if startOK && endOK {
132				conflict, warnings := availability.FindConflict(index[key], siteTZ, queryStart, queryEnd)
133				for _, w := range warnings {
134					log.Printf("availability: data quality warning: booking %s: %s", w.BookingID, w.Reason)
135				}
136				if conflict != nil {
137					bookingAvailable = false
138					// Operator identity (name, phone, SSN fragment, DOB, ...) is
139					// never included here (A6) - Part 1 doesn't need it to answer
140					// "is it free", and it was the single largest PII leak found
141					// in the inherited code. If a future screen needs "who has
142					// it booked", that's a new, explicitly role-gated endpoint,
143					// not a reason to bring SELECT * back into this response.
144					full := map[string]any{
145						"booking_id": conflict.BookingID,
146						"site_id":    conflict.SiteID,
147						"start_at":   conflict.StartAt,
148						"end_at":     conflict.EndAt,
149						"status":     conflict.Status,
150					}
151	
152					// Redact site/time/booking detail unless the caller has a
153					// stated business reason to see it: ops_director always;
154					// superintendent/foreman only for a conflict at their own
155					// site. subcontractor and safety_manager never get full
156					// detail here, regardless of their site_ids (safety_manager's
157					// "*" describes cert-oversight scope, not booking oversight;
158					// subcontractor is an outside company). An unrecognized role
159					// falls through to the same redacted default.
160					if user != nil && (fullDetailRole(user.Role) || (siteMatchedRole(user.Role) && hasSite(user.SiteIDs, conflict.SiteID))) {
161						conflictOut = full
162					} else {
163						conflictOut = map[string]any{"exists": true}
164					}
165				}
166			}
167	
168			// maintenanceStatus is "unknown" whenever fleetCache isn't wired up or
169			// the query window is unparsed - never silently "ok". available is a
170			// function of BOTH signals, not just bookings: this is the fix for the
171			// seam a prior review flagged as the one thing that could still make
172			// Dana's complaint ("looks free, isn't") recur through FleetCare
173			// specifically. No consumer can forget to check maintenance.status
174			// separately, because it's already folded into the one boolean.
175			maintenanceStatus := "unknown"
176			if fleetCache != nil && startOK && endOK {
177				maintenanceStatus, _ = fleetCache.Status(tag, time.Now(), queryStart, queryEnd)
178			}
179			availableOut := bookingAvailable && maintenanceStatus == "ok"
180	
181			// daily_rate_usd is Lumen's internal cost data; it has no business
182			// reason to reach a subcontractor or any role outside the people who
183			// manage the budget (confirmed live, this engagement: it was
184			// leaking to every role, including outside companies).
185			if user == nil || !rateVisibleRoles[user.Role] {
186				delete(item, "daily_rate_usd")
187			}
188	
189			item["available"] = availableOut
190			item["conflict"] = conflictOut
191			item["maintenance"] = map[string]any{"status": maintenanceStatus}
192			results = append(results, item)
193		}
194	
195		w.Header().Set("Content-Type", "application/json")
196		json.NewEncoder(w).Encode(map[string]any{"data": results})
197	}
198	
199	// parseQueryTime accepts a full RFC3339 timestamp or a plain "YYYY-MM-DD"
200	// date (treated as UTC midnight). Interim, pending the validation increment.
201	// writeError sends a consistent, actionable JSON error body. It never
202	// includes internal detail (SQL, file paths, stack traces) - just enough
203	// for a client to fix its request.
204	func writeError(w http.ResponseWriter, status int, message string) {
205		w.Header().Set("Content-Type", "application/json")
206		w.WriteHeader(status)
207		json.NewEncoder(w).Encode(map[string]string{"error": message})
208	}
209	
210	func parseQueryTime(raw string) (time.Time, bool) {
211		if raw == "" {
212			return time.Time{}, false
213		}
214		if t, err := time.Parse(time.RFC3339, raw); err == nil {
215			return t.UTC(), true
216		}
217		if t, err := time.Parse("2006-01-02", raw); err == nil {
218			return t.UTC(), true
219		}
220		return time.Time{}, false
221	}
222	
223	func asString(v any) string {
224		s, _ := v.(string)
225		return s
226	}
227	
228	func loadAllBookings() []availability.Booking {
229		rows, err := db.DB.Query("SELECT booking_id, asset_tag, site_id, start_at, end_at, operator_id, status FROM bookings ORDER BY booking_id")
230		if err != nil {
231			panic(err)
232		}
233		defer rows.Close()
234		var out []availability.Booking
235		for rows.Next() {
236			var b availability.Booking
237			var operatorID sql.NullString
238			if err := rows.Scan(&b.BookingID, &b.AssetTag, &b.SiteID, &b.StartAt, &b.EndAt, &operatorID, &b.Status); err != nil {
239				panic(err)
240			}
241			b.OperatorID = operatorID.String
242			out = append(out, b)
243		}
244		return out
245	}
246	
247	func loadSiteTimezones() func(siteID string) *time.Location {
248		rows, err := db.DB.Query("SELECT site_id, timezone FROM sites")
249		if err != nil {
250			panic(err)
251		}
252		defer rows.Close()
253		tz := map[string]*time.Location{}
254		for rows.Next() {
255			var siteID, timezone string
256			if err := rows.Scan(&siteID, &timezone); err != nil {
257				panic(err)
258			}
259			loc, err := time.LoadLocation(timezone)
260			if err != nil {
261				log.Printf("availability: unknown timezone %q for site %q, defaulting to UTC", timezone, siteID)
262				loc = time.UTC
263			}
264			tz[siteID] = loc
265		}
266		return func(siteID string) *time.Location {
267			if loc, ok := tz[siteID]; ok {
268				return loc
269			}
270			return time.UTC
271		}
272	}
273	
274	// scanAll turns rows into a slice of column->value maps.
275	func scanAll(rows *sql.Rows) []map[string]any {
276		defer rows.Close()
277		cols, _ := rows.Columns()
278		out := []map[string]any{}
279		for rows.Next() {
280			vals := make([]any, len(cols))
281			ptrs := make([]any, len(cols))
282			for i := range vals {
283				ptrs[i] = &vals[i]
284			}
285			rows.Scan(ptrs...)
286			m := map[string]any{}
287			for i, c := range cols {
288				if b, ok := vals[i].([]byte); ok {
289					m[c] = string(b)
290				} else {
291					m[c] = vals[i]
292				}
293			}
294			out = append(out, m)
295		}
296		return out
297	}
