package db

import (
	"database/sql"
	"log"
	"path/filepath"

	"lumen/equipment-api/internal/config"
)

var DB *sql.DB

func Open() {
	dbPath := config.Get("DB_PATH", "db/lumen.db")
	path := dbPath
	if !filepath.IsAbs(dbPath) {
		// An absolute DB_PATH (e.g. a disposable test database, or a
		// mounted volume path in some deployments) is used as-is;
		// filepath.Join would otherwise prefix it with RepoRoot and
		// silently produce a wrong, usually nonexistent, path.
		path = filepath.Join(config.RepoRoot(), dbPath)
	}
	var err error
	DB, err = sql.Open(driverName, path)
	if err != nil {
		log.Fatal(err)
	}
	// WAL mode: a reservation write (Part 2) holds SQLite's single write
	// lock for the duration of its transaction; without WAL, readers
	// (availability checks, Part 1) would block on that writer too.
	// Verified empirically in docs/decisions/0002-reservation-concurrency-control.md
	// (a read completed in ~46ms while a writer held a 300ms lock, under WAL).
	// journal_mode is a persistent, file-level setting - this only needs to
	// run once per process, but is idempotent to run on every Open().
	if _, err := DB.Exec("PRAGMA journal_mode=WAL"); err != nil {
		log.Fatal("db: failed to enable WAL mode: ", err)
	}
	// Bounds how long a writer blocks on SQLite's single write lock before
	// giving up with SQLITE_BUSY (ADR 0002): ordinary contention between a
	// couple of foremen a few hundred ms apart resolves silently; pathological
	// contention still bounds out to a catchable error instead of hanging.
	// 3s matches the FleetCare client's own timeout bound from Part 1.
	if _, err := DB.Exec("PRAGMA busy_timeout=3000"); err != nil {
		log.Fatal("db: failed to set busy_timeout: ", err)
	}
}

