	ctx := r.Context()
	conn, err := db.DB.Conn(ctx)
	if err != nil {
		log.Printf("reservations: acquiring connection: %v", err)
		writeError(w, http.StatusInternalServerError, "internal server error")
		return
	}
	defer conn.Close()

