		"site_id":     req.SiteID,
		"start_at":    startUTC,
		"end_at":      endUTC,
		"status":      req.Status,
		"operator_id": nullableString(operatorIDVal),
		"expires_at":  nullableString(expiresAtUTC),
		"booked_by":   user.Sub,
		"created_at":  nowUTC.Format(time.RFC3339),
	}})
}

