1	package handlers
2	
3	import (
4		"context"
5		"crypto/rand"
6		"database/sql"
7		"encoding/hex"
8		"encoding/json"
9		"errors"
10		"fmt"
11		"log"
12		"net/http"
13		"time"
14	
15		sqlite3 "modernc.org/sqlite"
16		sqlite3lib "modernc.org/sqlite/lib"
17	
18		"lumen/equipment-api/internal/auth"
19		"lumen/equipment-api/internal/availability"
20		"lumen/equipment-api/internal/certs"
21		"lumen/equipment-api/internal/db"
22	)
23	
24	// This file implements only POST /api/reservations (docs/plan/02-reservations.md,
25	// docs/decisions/0002-reservation-concurrency-control.md). The confirm and
26	// release endpoints, and the idempotency-key table (plan tasks 4 and 5), are
27	// approved in design but deliberately NOT built here - a separate pass, per
28	// instruction. A reservation created here can be "tentative" or "confirmed"
29	// (per the approved lifecycle), but nothing in this file can transition one
30	// afterward.
31	
32	type createReservationRequest struct {
33		AssetTag   string `json:"asset_tag"`
34		SiteID     string `json:"site_id"`
35		Start      string `json:"start"`
36		End        string `json:"end"`
37		Status     string `json:"status"`
38		OperatorID string `json:"operator_id"`
39		ExpiresAt  string `json:"expires_at"`
40	}
41	
42	// POST /api/reservations
43	//
44	// Order: decode/validate request shape -> authorize (B1) -> resolve
45	// equipment/site/operator and check certification (B3/B4) -> only then open
46	// the write transaction that holds the overlap check and the INSERT
47	// together. Everything before the transaction is read-only and does not
48	// need the write lock; only the check-then-insert sequence does.
49	func CreateReservation(w http.ResponseWriter, r *http.Request) {
50		var req createReservationRequest
51		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
52			writeError(w, http.StatusBadRequest, "malformed JSON body")
53			return
54		}
55	
56		if req.AssetTag == "" || req.SiteID == "" || req.Start == "" || req.End == "" || req.Status == "" {
57			writeError(w, http.StatusBadRequest, "asset_tag, site_id, start, end, and status are required")
58			return
59		}
60	
61		start, err := time.Parse(time.RFC3339, req.Start)
62		if err != nil {
63			writeError(w, http.StatusBadRequest, "start must be an RFC3339 timestamp")
64			return
65		}
66		end, err := time.Parse(time.RFC3339, req.End)
67		if err != nil {
68			writeError(w, http.StatusBadRequest, "end must be an RFC3339 timestamp")
69			return
70		}
71		if !end.After(start) {
72			writeError(w, http.StatusBadRequest, "end must be after start")
73			return
74		}
75	
76		if req.Status != "tentative" && req.Status != "confirmed" {
77			writeError(w, http.StatusBadRequest, `status must be "tentative" or "confirmed"`)
78			return
79		}
80	
81		var expiresAt time.Time
82		if req.Status == "tentative" {
83			// Point 3 of the approved tentative-hold policy: every hold has a
84			// required expiration, not an optional one.
85			if req.ExpiresAt == "" {
86				writeError(w, http.StatusBadRequest, `expires_at is required when status is "tentative"`)
87				return
88			}
89			expiresAt, err = time.Parse(time.RFC3339, req.ExpiresAt)
90			if err != nil {
91				writeError(w, http.StatusBadRequest, "expires_at must be an RFC3339 timestamp")
92				return
93			}
94			if !expiresAt.After(time.Now()) {
95				writeError(w, http.StatusBadRequest, "expires_at must be in the future")
96				return
97			}
98		} else if req.ExpiresAt != "" {
99			writeError(w, http.StatusBadRequest, `expires_at must not be set when status is "confirmed"`)
100			return
101		}
102	
103		user := auth.UserFrom(r)
104		if user == nil {
105			// RequireAuth already guarantees this; defensive only.
106			writeError(w, http.StatusUnauthorized, "invalid or missing token")
107			return
108		}
109	
110		// B1: ops_director may book anywhere; superintendent/foreman only at a
111		// site in their own site_ids; everyone else (subcontractor,
112		// safety_manager) cannot create a reservation at all. Unlike Part 1's
113		// read path, there's no partial/redacted response for a write - it's a
114		// clean 403.
115		authorized := false
116		switch user.Role {
117		case "ops_director":
118			authorized = true
119		case "superintendent", "foreman":
120			authorized = user.CanAccessSite(req.SiteID)
121		}
122		if !authorized {
123			writeError(w, http.StatusForbidden, fmt.Sprintf("not authorized to book at site %s", req.SiteID))
124			return
125		}
126	
127		equipment, err := loadEquipment(req.AssetTag)
128		if err != nil {
129			log.Printf("reservations: loading equipment: %v", err)
130			writeError(w, http.StatusInternalServerError, "internal server error")
131			return
132		}
133		if equipment == nil || equipment.Status != "active" {
134			writeError(w, http.StatusBadRequest, fmt.Sprintf("unknown or inactive asset_tag %q", req.AssetTag))
135			return
136		}
137	
138		site, err := loadSite(req.SiteID)
139		if err != nil {
140			log.Printf("reservations: loading site: %v", err)
141			writeError(w, http.StatusInternalServerError, "internal server error")
142			return
143		}
144		if site == nil {
145			writeError(w, http.StatusBadRequest, fmt.Sprintf("unknown site_id %q", req.SiteID))
146			return
147		}
148	
149		// B4: cert-required equipment needs a real operator_id; equipment with
150		// no required_cert does not. An operator_id given for non-cert-required
151		// equipment is still validated against the operators table if present,
152		// so a typo'd operator_id is never silently accepted.
153		if equipment.RequiredCert != "" && req.OperatorID == "" {
154			writeError(w, http.StatusBadRequest, fmt.Sprintf("operator_id is required for equipment requiring %s", equipment.RequiredCert))
155			return
156		}
157		if req.OperatorID != "" {
158			operator, err := loadOperator(req.OperatorID)
159			if err != nil {
160				log.Printf("reservations: loading operator: %v", err)
161				writeError(w, http.StatusInternalServerError, "internal server error")
162				return
163			}
164			if operator == nil {
165				writeError(w, http.StatusBadRequest, fmt.Sprintf("unknown operator_id %q", req.OperatorID))
166				return
167			}
168			if equipment.RequiredCert != "" {
169				// B3: evaluated against the booking's end, in the booking
170				// site's timezone - a cert good "through" the start isn't
171				// enough if it lapses mid-booking.
172				loc := loadSiteTimezones()(req.SiteID)
173				held, parseErrs := certs.ParseCertifications(operator.Certifications, loc)
174				for _, e := range parseErrs {
175					log.Printf("reservations: operator %s: %v", req.OperatorID, e)
176				}
177				if !certs.HasValidCert(held, equipment.RequiredCert, end) {
178					hasAny := false
179					for _, c := range held {
180						if c.Name == equipment.RequiredCert {
181							hasAny = true
182						}
183					}
184					if hasAny {
185						writeError(w, http.StatusUnprocessableEntity, fmt.Sprintf("operator %s's %s certification expires before the booking ends", req.OperatorID, equipment.RequiredCert))
186					} else {
187						writeError(w, http.StatusUnprocessableEntity, fmt.Sprintf("operator %s does not hold the required %s certification", req.OperatorID, equipment.RequiredCert))
188					}
189					return
190				}
191			}
192		}
193	
194		bookingID, err := generateBookingID()
195		if err != nil {
196			log.Printf("reservations: generating booking id: %v", err)
197			writeError(w, http.StatusInternalServerError, "internal server error")
198			return
199		}
200	
201		startUTC := start.UTC().Format(time.RFC3339)
202		endUTC := end.UTC().Format(time.RFC3339)
203		nowUTC := time.Now().UTC()
204		var expiresAtUTC sql.NullString
205		if req.Status == "tentative" {
206			expiresAtUTC = sql.NullString{String: expiresAt.UTC().Format(time.RFC3339), Valid: true}
207		}
208		var operatorIDVal sql.NullString
209		if req.OperatorID != "" {
210			operatorIDVal = sql.NullString{String: req.OperatorID, Valid: true}
211		}
212	
213		ctx := r.Context()
214		conn, err := db.DB.Conn(ctx)
215		if err != nil {
216			log.Printf("reservations: acquiring connection: %v", err)
217			writeError(w, http.StatusInternalServerError, "internal server error")
218			return
219		}
220		defer conn.Close()
221	
222		// BEGIN IMMEDIATE acquires SQLite's write lock up front (not lazily on
223		// first write) - see ADR 0002. Everything from here to COMMIT/ROLLBACK
224		// runs on this one raw connection, never database/sql's Tx wrapper, so
225		// the busy/trigger error codes surface exactly as the ADR's experiments
226		// observed them.
227		if _, err := conn.ExecContext(ctx, "BEGIN IMMEDIATE"); err != nil {
228			if isBusy(err) {
229				writeBusy(w)
230				return
231			}
232			log.Printf("reservations: BEGIN IMMEDIATE: %v", err)
233			writeError(w, http.StatusInternalServerError, "internal server error")
234			return
235		}
236		committed := false
237		defer func() {
238			if !committed {
239				if _, rbErr := conn.ExecContext(context.Background(), "ROLLBACK"); rbErr != nil {
240					log.Printf("reservations: rollback: %v", rbErr)
241				}
242			}
243		}()
244	
245		conflict, err := findActiveConflict(ctx, conn, equipment.AssetTag, startUTC, endUTC)
246		if err != nil {
247			log.Printf("reservations: overlap pre-check: %v", err)
248			writeError(w, http.StatusInternalServerError, "internal server error")
249			return
250		}
251		if conflict != nil {
252			writeConflictResponse(w, user, conflict)
253			return
254		}
255	
256		_, err = conn.ExecContext(ctx,
257			`INSERT INTO bookings (booking_id, asset_tag, site_id, start_at, end_at, operator_id, booked_by, status, notes, start_at_utc, end_at_utc, expires_at_utc)
258			 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
259			bookingID, equipment.AssetTag, req.SiteID,
260			startUTC, endUTC,
261			operatorIDVal, user.Sub, req.Status, sql.NullString{},
262			startUTC, endUTC, expiresAtUTC,
263		)
264		if err != nil {
265			var sqliteErr *sqlite3.Error
266			if errors.As(err, &sqliteErr) && sqliteErr.Code() == sqlite3lib.SQLITE_CONSTRAINT_TRIGGER {
267				// The app-level pre-check above found nothing, but the trigger -
268				// which runs inside this same transaction, against the same
269				// committed state - disagrees. Since BEGIN IMMEDIATE has held
270				// the write lock since before the pre-check, nothing else could
271				// have written in between; this is the trigger backstop doing
272				// its job against a gap in the pre-check logic itself, which is
273				// worth knowing about, not just silently absorbing as a normal
274				// conflict.
275				log.Printf("reservations: trigger rejected an insert the app-level pre-check missed: asset_tag=%s", equipment.AssetTag)
276				writeError(w, http.StatusConflict, "conflict")
277				return
278			}
279			if isBusy(err) {
280				writeBusy(w)
281				return
282			}
283			log.Printf("reservations: insert failed: %v", err)
284			writeError(w, http.StatusInternalServerError, "internal server error")
285			return
286		}
287	
288		if _, err := conn.ExecContext(ctx, "COMMIT"); err != nil {
289			if isBusy(err) {
290				writeBusy(w)
291				return
292			}
293			log.Printf("reservations: commit failed: %v", err)
294			writeError(w, http.StatusInternalServerError, "internal server error")
295			return
296		}
297		committed = true
298	
299		w.Header().Set("Content-Type", "application/json")
300		w.WriteHeader(http.StatusCreated)
301		json.NewEncoder(w).Encode(map[string]any{"data": map[string]any{
302			"booking_id":  bookingID,
303			"asset_tag":   equipment.AssetTag,
304			"site_id":     req.SiteID,
305			"start_at":    startUTC,
306			"end_at":      endUTC,
307			"status":      req.Status,
308			"operator_id": nullableString(operatorIDVal),
309			"expires_at":  nullableString(expiresAtUTC),
310			"booked_by":   user.Sub,
311			"created_at":  nowUTC.Format(time.RFC3339),
312		}})
313	}
314	
315	// findActiveConflict runs, inside the caller's transaction, the exact same
316	// overlap predicate as the no_overlapping_active_bookings trigger (schema.sql)
317	// against the new booking's canonical UTC window - so a real conflict is
318	// reported here, with detail, before ever attempting the INSERT whose own
319	// rejection (by design) carries none.
320	func findActiveConflict(ctx context.Context, conn *sql.Conn, assetTag, startUTC, endUTC string) (*availability.Conflict, error) {
321		row := conn.QueryRowContext(ctx, `
322			SELECT booking_id, site_id, start_at, end_at, status, operator_id
323			FROM bookings
324			WHERE asset_tag = ?
325			  AND (
326			    status = 'confirmed'
327			    OR (status = 'tentative' AND (expires_at_utc IS NULL OR expires_at_utc > datetime('now')))
328			  )
329			  AND ? < end_at_utc
330			  AND start_at_utc < ?
331			LIMIT 1`,
332			assetTag, startUTC, endUTC,
333		)
334		var c availability.Conflict
335		var operatorID sql.NullString
336		err := row.Scan(&c.BookingID, &c.SiteID, &c.StartAt, &c.EndAt, &c.Status, &operatorID)
337		if errors.Is(err, sql.ErrNoRows) {
338			return nil, nil
339		}
340		if err != nil {
341			return nil, err
342		}
343		c.OperatorID = operatorID.String
344		return &c, nil
345	}
346	
347	// writeConflictResponse applies Part 1's exact redaction rule (fullDetailRole /
348	// siteMatchedRole / hasSite, availability.go) to a write-path conflict, so a
349	// caller never learns more about someone else's booking via a 409 than they
350	// would have via the read endpoint's conflict detail.
351	func writeConflictResponse(w http.ResponseWriter, user *auth.User, c *availability.Conflict) {
352		var conflictOut map[string]any
353		if user != nil && (fullDetailRole(user.Role) || (siteMatchedRole(user.Role) && hasSite(user.SiteIDs, c.SiteID))) {
354			conflictOut = map[string]any{
355				"booking_id": c.BookingID,
356				"site_id":    c.SiteID,
357				"start_at":   c.StartAt,
358				"end_at":     c.EndAt,
359				"status":     c.Status,
360			}
361		} else {
362			conflictOut = map[string]any{"exists": true}
363		}
364		w.Header().Set("Content-Type", "application/json")
365		w.WriteHeader(http.StatusConflict)
366		json.NewEncoder(w).Encode(map[string]any{"error": "conflict", "conflict": conflictOut})
367	}
368	
369	func isBusy(err error) bool {
370		var sqliteErr *sqlite3.Error
371		return errors.As(err, &sqliteErr) && sqliteErr.Code() == sqlite3lib.SQLITE_BUSY
372	}
373	
374	func writeBusy(w http.ResponseWriter) {
375		w.Header().Set("Retry-After", "1")
376		writeError(w, http.StatusServiceUnavailable, "try again")
377	}
378	
379	func nullableString(v sql.NullString) any {
380		if !v.Valid {
381			return nil
382		}
383		return v.String
384	}
385	
386	func generateBookingID() (string, error) {
387		buf := make([]byte, 12)
388		if _, err := rand.Read(buf); err != nil {
389			return "", err
390		}
391		return "RES-" + hex.EncodeToString(buf), nil
392	}
393	
394	type equipmentRow struct {
395		AssetTag     string
396		Status       string
397		RequiredCert string
398	}
399	
400	// loadEquipment resolves a client-supplied asset_tag the same way Part 1
401	// resolves one from the messier bookings.csv data: via NormalizeTag, not an
402	// exact string match (docs/plan/02-reservations.md's validation section
403	// calls for reusing it explicitly). The equipment table is small (tens of
404	// rows), so a full scan here is simpler and clearer than pushing a
405	// normalization expression into SQL.
406	func loadEquipment(rawAssetTag string) (*equipmentRow, error) {
407		key := availability.NormalizeTag(rawAssetTag)
