26		mux.Handle("POST /api/reservations", auth.RequireAuth(authCfg, http.HandlerFunc(handlers.CreateReservation)))
27		// A custom Authorization header always triggers a CORS preflight
28		// (it isn't a "simple" header per the Fetch spec); without an OPTIONS
29		// response the browser never sends the real GET/POST at all. No auth
30		// here - preflight requests never carry credentials.
