32			w.WriteHeader(http.StatusNoContent)
33		})
34		mux.HandleFunc("OPTIONS /api/reservations", func(w http.ResponseWriter, r *http.Request) {
35			w.WriteHeader(http.StatusNoContent)
36		})
37	
38		return Wrap(mux)
39	}
40	
41	// Wrap applies the same middleware chain New() uses, so tests can exercise
42	// cors/logRequests/recoverErrors against an arbitrary handler without
43	// standing up the full route table.
44	func Wrap(next http.Handler) http.Handler {
45		return cors(logRequests(recoverErrors(next)))
46	}
47	
48	// allowedOrigins is a small, explicit allow-list rather than "*" - a
49	// wildcard combined with Allow-Credentials is both an invalid combination
50	// per the CORS spec and an unnecessary exposure. CORS_ALLOWED_ORIGINS is a
51	// comma-separated override for other environments (e.g. a deployed
52	// frontend origin); the dev server origin is the default.
53	func allowedOrigins() []string {
54		raw := config.Get("CORS_ALLOWED_ORIGINS", "http://localhost:5173")
55		var out []string
56		for _, o := range strings.Split(raw, ",") {
57			if o = strings.TrimSpace(o); o != "" {
58				out = append(out, o)
59			}
60		}
61		return out
62	}
63	
64	func cors(next http.Handler) http.Handler {
65		allowed := allowedOrigins()
66		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
67			origin := r.Header.Get("Origin")
68			for _, a := range allowed {
69				if origin == a {
